// PROJETO SM3 — PRODUCTION PACKAGE v1 (DRY RUN)
// Builds deterministic production packages from content that passed the human gate.
// No rendering, no Drive exports and no spreadsheet writes in this version.

const contentRows = $('READ — PRODUCTION CONTENT').all().map(i => i.json);
const mediaRows = $('READ — PRODUCTION MEDIA').all().map(i => i.json);
const assetsRows = $('READ — IDENTITY ASSETS').all().map(i => i.json);
const rulesRows = $('READ — IDENTITY RULES').all().map(i => i.json);
const engineRows = $('READ — COMPOSITION ENGINE').all().map(i => i.json);
const templateRows = $input.all().map(i => i.json);

const mediaById = new Map(
  mediaRows
    .filter(r => String(r.ID_MIDIA || '').trim())
    .map(r => [String(r.ID_MIDIA).trim(), r])
);

const templatesById = new Map(
  templateRows
    .filter(r => String(r.ID_TEMPLATE || '').trim())
    .map(r => [String(r.ID_TEMPLATE).trim(), r])
);

const activeRules = rulesRows
  .filter(r => String(r.STATUS || '').trim().toUpperCase() === 'ATIVA')
  .map(r => ({
    id: r.ID_REGRA,
    scope: r.ESCOPO,
    rule: r.REGRA,
    priority: r.PRIORIDADE,
    application: r.APLICAÇÃO,
    exception: r.EXCEÇÃO || ''
  }));

const availableAssets = assetsRows
  .filter(r => {
    const s = String(r.STATUS || '').trim().toUpperCase();
    return ['ATIVO','OFICIAL','MUTÁVEL'].includes(s);
  })
  .map(r => ({
    id: r.ID_ATIVO,
    category: r.CATEGORIA,
    name: r.NOME,
    type: r.TIPO,
    status: r.STATUS,
    authority: r.AUTORIDADE,
    function: r['FUNÇÃO'] || '',
    recommended_use: r.USO_RECOMENDADO || '',
    restrictions: r['RESTRIÇÕES'] || '',
    drive_id: r.ID_DRIVE || '',
    variant: r.VARIANTE || '',
    priority: r.PRIORIDADE || ''
  }));

const activeProfiles = engineRows
  .filter(r => String(r.STATUS || '').trim().toUpperCase() === 'ATIVO');

function extractMediaIds(value) {
  const text = String(value || '');
  const matches = text.match(/M\d{4}/g) || [];
  return [...new Set(matches)];
}

function targetFor(format) {
  const f = String(format || '').trim().toUpperCase();
  if (f === 'REEL') return {route_key:'REEL', width:1080, height:1920, fps:30, container:'mp4'};
  if (f === 'CARROSSEL') return {route_key:'CAROUSEL', width:1080, height:1350, fps:null, container:'jpg'};
  if (f === 'FOTO') return {route_key:'IMAGE', width:1080, height:1350, fps:null, container:'jpg'};
  if (f === 'STORY') return {route_key:'STORY', width:1080, height:1920, fps:null, container:'jpg_or_mp4'};
  return {route_key:'BLOCKED', width:null, height:null, fps:null, container:null};
}

function chooseProfile(content) {
  const objective = String(content.OBJETIVO || '').toUpperCase();
  const format = String(content.FORMATO || '').toUpperCase();

  // Processo / bastidores / evolução: use MC_002 when available.
  if (
    objective.includes('PROCESS') ||
    objective.includes('EXECU') ||
    objective.includes('EVOLU') ||
    objective.includes('BASTIDOR')
  ) {
    return activeProfiles.find(p => String(p.ID_PERFIL) === 'MC_002') || activeProfiles[0] || null;
  }

  // Portfolio/photo: MC_001.
  if (format === 'FOTO' || objective.includes('PORTF')) {
    return activeProfiles.find(p => String(p.ID_PERFIL) === 'MC_001') || activeProfiles[0] || null;
  }

  return activeProfiles[0] || null;
}

const eligible = contentRows.filter(r =>
  String(r.ROUTING_STATUS || '').trim().toUpperCase() === 'ROUTED' &&
  String(r.ROUTING_TARGET || '').trim().toUpperCase() === 'PRODUCTION' &&
  String(r.PRODUCTION_STATUS || '').trim().toUpperCase() === 'READY' &&
  String(r.EDITORIAL_STATUS || '').trim().toUpperCase() === 'ACTIVE' &&
  String(r.APPROVAL_COMMITTED_STATUS || '').trim().toUpperCase() === 'APROVADO'
);

if (eligible.length === 0) {
  return [{
    json: {
      no_work: true,
      route_key: 'NO_WORK',
      status: 'NO_PRODUCTION_READY_CONTENT',
      message: 'Nenhum conteúdo está pronto para produção.',
      checked_at: new Date().toISOString()
    }
  }];
}

const out = [];

for (const c of eligible) {
  const mediaIds = extractMediaIds(c.BRUTOS_USADOS);
  const missingMedia = mediaIds.filter(id => !mediaById.has(id));
  const media = mediaIds
    .filter(id => mediaById.has(id))
    .map(id => {
      const m = mediaById.get(id);
      return {
        media_id: id,
        project_id: m.ID_PROJETO || '',
        file_name: m.ARQUIVO || '',
        drive_file_id: m.DRIVE_FILE_ID || '',
        link_drive: m.LINK_DRIVE || '',
        media_type: m.TIPO || '',
        relative_path: m.RELATIVE_PATH || '',
        storage_status: m.STORAGE_STATUS || '',
        analysis_stage: m.ANALYSIS_STAGE || '',
        shot_type: m.SHOT_TYPE || '',
        best_moment: m.MELHOR_TRECHO || '',
        visual_summary: m['CONTEÚDO_VISUAL'] || ''
      };
    });

  const templateId = String(c.TEMPLATE_ID || '').trim();
  const template = templatesById.get(templateId) || null;
  const profile = chooseProfile(c);
  const target = targetFor(c.FORMATO);

  const blockingReasons = [];

  if (target.route_key === 'BLOCKED') blockingReasons.push(`UNSUPPORTED_FORMAT:${c.FORMATO}`);
  if (mediaIds.length === 0) blockingReasons.push('NO_SOURCE_MEDIA');
  if (missingMedia.length) blockingReasons.push(`MISSING_MEDIA:${missingMedia.join(',')}`);
  if (media.some(m => String(m.storage_status || '').toUpperCase() !== 'ONLINE')) {
    blockingReasons.push('SOURCE_MEDIA_OFFLINE');
  }
  if (!templateId) blockingReasons.push('NO_TEMPLATE_ID');
  if (!template) blockingReasons.push(`TEMPLATE_NOT_FOUND:${templateId || 'EMPTY'}`);
  if (!profile) blockingReasons.push('NO_COMPOSITION_PROFILE');

  out.push({
    json: {
      no_work: false,
      route_key: blockingReasons.length ? 'BLOCKED' : target.route_key,
      production_ready: blockingReasons.length === 0,
      blocking_reasons: blockingReasons,

      content_id: c.ID_CONTEÚDO,
      project_id: c.ID_PROJETO,
      title: c.TÍTULO_INTERNO,
      format: c.FORMATO,
      objective: c.OBJETIVO,
      priority: c.PRIORIDADE,
      hook: c.HOOK || '',
      script: c.ROTEIRO || '',
      caption: c.LEGENDA || '',
      cta: c.CTA || '',
      approval_notes: c.APPROVAL_NOTES || '',

      source_media_ids: mediaIds,
      source_media: media,

      template_id: templateId,
      template: template ? {
        id: template.ID_TEMPLATE,
        name: template.NOME,
        format: template.FORMATO,
        dimension: template.DIMENSAO || '',
        media_zone: template.ZONA_MIDIA || '',
        text_zone: template.ZONA_TEXTO || '',
        signature: template.ASSINATURA || '',
        crop_rule: template.REGRA_CROP || '',
        text_rule: template.REGRA_TEXTO || ''
      } : null,

      composition_profile: profile ? {
        id: profile.ID_PERFIL,
        content_type: profile.TIPO_CONTEUDO,
        objective: profile.OBJETIVO,
        media_prominence: profile.PROTAGONISMO_MIDIA,
        identity_density: profile.DENSIDADE_IDENTIDADE,
        aux_element_count: profile.QTD_ELEMENTOS_AUX,
        logo: profile.LOGO,
        stamp: profile.CARIMBO,
        preferred_assets: profile.ATIVOS_PREFERENCIAIS,
        avoid: profile.EVITAR,
        composition: profile.COMPOSICAO
      } : null,

      identity_assets: availableAssets,
      identity_rules: activeRules,

      render_target: {
        width: target.width,
        height: target.height,
        fps: target.fps,
        container: target.container
      },

      safeguards: {
        human_approval_required_before_publish: true,
        exif_transpose_required: true,
        semantic_crop_required: true,
        preserve_tattoo_geometry: true,
        no_random_japanese_text: true,
        logo_and_stamp_protected: true
      },

      dry_run: true,
      built_at: new Date().toISOString()
    }
  });
}

return out;

const items=$input.all().map(i=>i.json);
return [{json:{
  dry_run:true,
  status:'REEL_READY',
  count:items.length,
  content_ids:items.map(x=>x.content_id).filter(Boolean),
  packages:items
}}];

const items=$input.all().map(i=>i.json);
return [{json:{
  dry_run:true,
  status:'CAROUSEL_READY',
  count:items.length,
  content_ids:items.map(x=>x.content_id).filter(Boolean),
  packages:items
}}];

const items=$input.all().map(i=>i.json);
return [{json:{
  dry_run:true,
  status:'IMAGE_READY',
  count:items.length,
  content_ids:items.map(x=>x.content_id).filter(Boolean),
  packages:items
}}];

const items=$input.all().map(i=>i.json);
return [{json:{
  dry_run:true,
  status:'STORY_READY',
  count:items.length,
  content_ids:items.map(x=>x.content_id).filter(Boolean),
  packages:items
}}];

const items=$input.all().map(i=>i.json);
return [{json:{
  dry_run:true,
  status:'BLOCKED',
  count:items.length,
  content_ids:items.map(x=>x.content_id).filter(Boolean),
  packages:items
}}];

return [{json:{
  dry_run:true,
  status:'NO_WORK',
  message:'Nenhum conteúdo está pronto para produção.'
}}];
